{"content":"from collections import Counter
from itertools import combinations


# Prices in cents for a discounted group of distinct titles.
_GROUP_PRICES = (0, 800, 1520, 2160, 2560, 3000)


def total(basket):
    """Return the lowest possible basket price in integer cents."""
    initial = tuple(sorted(Counter(basket).values(), reverse=True))
    prices = {(): 0}
    pending = [(initial, False)]

    # Evaluate the memoized recurrence with a stack rather than recursion,
    # so large baskets do not run into Python's recursion limit.
    while pending:
        counts, expanded = pending.pop()
        if counts in prices:
            continue

        options = set()
        for size in range(1, len(counts) + 1):
            for group in combinations(range(len(counts)), size):
                remaining = list(counts)
                for index in group:
                    remaining[index] -= 1
                # Title identities do not affect prices. Canonicalizing counts
                # lets equivalent remaining baskets share the same result.
                state = tuple(sorted((n for n in remaining if n), reverse=True))
                options.add((state, _GROUP_PRICES[size]))

        if expanded:
            prices[counts] = min(price + prices[state] for state, price in options)
        else:
            pending.append((counts, True))
            pending.extend((state, False) for state, _ in options if state not in prices)

    return prices[initial]
