{"content":"import unittest
from functools import lru_cache
from itertools import product

from book_store import total


class BookStoreTests(unittest.TestCase):
    def test_empty_basket(self):
        self.assertEqual(total([]), 0)

    def test_each_discount_tier(self):
        for size, expected in enumerate((800, 1520, 2160, 2560, 3000), 1):
            with self.subTest(size=size):
                self.assertEqual(total(list(range(1, size + 1))), expected)

    def test_duplicate_cannot_join_the_same_group(self):
        self.assertEqual(total([1, 1, 2, 3]), 2960)
        self.assertEqual(total([2, 2, 2]), 2400)

    def test_two_groups_of_four_beat_five_and_three(self):
        self.assertEqual(total([1, 1, 2, 2, 3, 3, 4, 5]), 5120)

    def test_multiple_regroupings(self):
        self.assertEqual(total([1] * 5 + [2] * 5 + [3] * 4 + [4] * 5 + [5] * 4), 14120)

    def test_order_and_title_labels_do_not_matter(self):
        basket = ["a", "b", "c", "d", "e", "a", "b", "c"]
        self.assertEqual(total(basket), 5120)
        self.assertEqual(total(basket[::-1]), 5120)

    def test_large_basket_does_not_require_recursion(self):
        self.assertEqual(total([1] * 1500), 1200000)

    def test_does_not_modify_input(self):
        basket = [3, 1, 2, 1]
        total(basket)
        self.assertEqual(basket, [3, 1, 2, 1])

    def test_small_baskets_against_labeled_exhaustive_search(self):
        # Independent oracle: keep title identities and enumerate bit masks
        # instead of merging baskets with equivalent count distributions.
        @lru_cache(maxsize=None)
        def exhaustive(counts):
            if not any(counts):
                return 0
            best = sum(counts) * 800
            for mask in range(1, 32):
                selected = [i for i in range(5) if mask & (1 << i)]
                if any(counts[i] == 0 for i in selected):
                    continue
                remaining = tuple(n - (i in selected) for i, n in enumerate(counts))
                size = len(selected)
                price = size * 800 * (100, 95, 90, 80, 75)[size - 1] // 100
                best = min(best, price + exhaustive(remaining))
            return best

        for counts in product(range(3), repeat=5):
            basket = [title for title, count in enumerate(counts) for _ in range(count)]
            with self.subTest(counts=counts):
                self.assertEqual(total(basket), exhaustive(counts))


if __name__ == "__main__":
    unittest.main()
